from lib import *
S = SS('s6')
steps = [
    step("七个请求都配了 callback 和 errback:200 与 302→200 走 callback(重定向被中间件处理掉了);404、500 走 errback,Failure 里是 scrapy.spidermiddlewares.httperror.HttpError,failure.value.response.status 能取到 404/500——HTTP 错误是 HttpErrorMiddleware 在爬虫中间件阶段抛出的;超时(DOWNLOAD_TIMEOUT=1,服务器睡 3 s)、连接被拒、DNS 失败也走 errback,2.19 里异常类是 scrapy.exceptions 下的 DownloadTimeoutError、DownloadConnectionRefusedError、CannotResolveHostError。stats 里 downloader/exception_count = 3,按类型各 1 个。", t=tl(S(1)), mark=lidx(S(1), '404  ', '500  ', '超时', '连接被拒', 'DNS 失败'), done=lidx(S(1), '200  ', '302→200'), kv=KV([['200、302→200', 'callback'], ['404、500', 'errback:HttpError(带 response)'], ['超时 / 连接被拒 / DNS', 'errback:scrapy.exceptions.Download…Error / CannotResolveHostError'], ['downloader/exception_count', '3']], ['404、500'])),
    step("回调自己抛异常(ValueError)时 errback 不会被调用:事件里只有 “callback 开始”,没有 errback;stats 里 spider_exceptions/count = 1、spider_exceptions/ValueError = 1,日志是 ERROR “Spider error processing …”。errback 只处理下载阶段和爬虫中间件 process_spider_input 阶段(HttpError 在这里)的失败,回调里的异常要自己 try/except,或者用爬虫中间件的 process_spider_exception。", t=tl(S(2)), mark=lidx(S(2), '事件', 'spider_exceptions'), kv=KV([['回调抛 ValueError', 'errback 不调用'], ['spider_exceptions/count', '1'], ['日志', 'Spider error processing …']], ['回调抛 ValueError'])),
    step("传数据:cb_kwargs 变成回调的关键字参数,meta 通过 response.meta 取。经过一次 302 重定向(/red → /ok),回调仍然收到 a=1、b=[2] 和 meta['m']='x',meta 里多了 redirect_reasons、redirect_times、redirect_ttl、redirect_urls;经过两次 503 重试(/flaky,retry/count = 2),cb_kwargs 和 meta['m'] 仍在,meta 多了 retry_times。两种请求的 meta 里还有 Scrapy 自己加的 download_latency、download_slot、download_timeout、is_start_request。", t=tl(S(3)), mark=lidx(S(3), 'redirect_reasons', 'retry_times'), done=lidx(S(3), 'a=1 b=[2]'), kv=KV([['cb_kwargs', '回调参数,重定向和重试后保留'], ['meta', '重定向后多 redirect_*,重试后多 retry_times'], ['Scrapy 自加的键', 'download_latency、download_slot、download_timeout、is_start_request']], ['cb_kwargs'])),
    step("cb_kwargs 和回调签名必须对得上,否则回调调用时 TypeError:缺少必需参数 b → TypeError: S.cb() missing 1 required positional argument: 'b';cb_kwargs 里多了回调不接受的 c → TypeError: S.cb() got an unexpected keyword argument 'c';回调加上 **kw 兜底就没事,kw 收到 {'c': 3}。这两个 TypeError 都计入 spider_exceptions,不会走 errback。", t=tl(S(4)), mark=lidx(S(4), 'missing 1 required', 'unexpected keyword'), done=lidx(S(4), '**kw'), kv=KV([['缺少参数', 'TypeError missing …'], ['多了参数', 'TypeError unexpected keyword'], ['**kw', '兜底,不报错']], ['缺少参数'])),
    step("哪些操作会带上 meta 和 cb_kwargs:response.follow('/a') 产生的新请求 meta 和 cb_kwargs 都是空的,什么都不继承;response.request.replace(url=…) 与 request.copy() 会把 meta 里的 k 和 Scrapy 自己加的 is_start_request、download_timeout、download_slot、download_latency 一起带上,cb_kwargs 也带上;copy() 的 meta 是新的字典(与原对象不是同一个)。直接 replace 一个旧请求,会把上一个请求的 download_latency 之类的内部键也复制到新请求里。", t=tl(S(5)), mark=lidx(S(5), 'follow', 'replace', 'copy'), kv=KV([['response.follow', 'meta、cb_kwargs 都为空'], ['request.replace / copy', '带上 meta(含 Scrapy 内部键)和 cb_kwargs'], ['copy 的 meta', '新字典,不共享']], ['response.follow'])),
]
A = mkarts('s6', 6, 'Scrapy,Request,callback,errback,cb_kwargs,meta,真实验证,动画演示',
    '实测 Scrapy 2.19 的 callback / errback / cb_kwargs / meta:404、500 走 errback(HttpError),超时、连接被拒、DNS 失败也走 errback(新的 Download…Error 异常类);回调里抛异常不触发 errback;cb_kwargs 与 meta 在重定向和重试后保留;response.follow 什么都不继承。',
    '一个 Request 带着 callback、errback、cb_kwargs、meta 去下载,回来以后哪一个会被调用、数据怎么传?这篇给 7 种不同结果的请求配上 callback 和 errback,再验证重定向、重试对 meta 的影响,以及 cb_kwargs 签名不匹配时的后果。',
    [('404、500', '都走 errback,Failure 里是 HttpError(带 response)'), ('0 次', '回调里抛异常时 errback 被调用的次数'), ('0 个', 'response.follow 产生的新请求从原请求继承到的 meta 和 cb_kwargs 键数')],
    [('errback 管什么', '<p>下载失败(超时、连接被拒、DNS 失败)和 HTTP 错误状态码(由 <code>HttpErrorMiddleware</code> 抛出的 <code>HttpError</code>)都走 errback。2.19 里下载异常是 <code>scrapy.exceptions</code> 下的 <code>DownloadTimeoutError</code> 等。</p>'),
     ('回调里的异常', '<p>回调里抛出的异常不会进 errback,而是计入 <code>spider_exceptions</code>,日志 <code>Spider error processing</code>。</p>'),
     ('meta 与 cb_kwargs 传数据', '<p><code>cb_kwargs</code> 作为回调的关键字参数传入,<code>meta</code> 通过 <code>response.meta</code> 访问。重定向和重试产生的新请求保留二者,并在 meta 里加上 <code>redirect_*</code> 或 <code>retry_times</code>。</p>'),
     ('签名要匹配', '<p>回调的参数要和 <code>cb_kwargs</code> 的键一一对应,多一个少一个都是 <code>TypeError</code>;回调带 <code>**kwargs</code> 可以兜底。</p>'),
     ('哪些操作继承数据', '<p><code>response.follow</code> 不继承 meta 和 cb_kwargs,要自己传;<code>Request.replace</code> / <code>copy</code> 会连同 Scrapy 内部加的键一起复制。</p>')],
    steps,
    [ENV_Y + '。每个情形是一个单文件 spider;服务器按路径返回 200 / 404 / 500 / 睡 3 s / 302 / 前两次 503;连接被拒用本机的 127.0.0.1:1,DNS 失败用保留域名 .invalid',
     '没有验证:errback 在 spider 中间件 process_spider_input 抛其它异常时的行为;callback 是别的对象的方法时(JOBDIR 序列化,见后面的文章);meta 里放大对象或不可序列化对象的后果;cb_kwargs 和 meta 在 HTTP 缓存命中时的表现;async def 回调抛异常的统计'],
    '回调与 errback')
